tests_spec:
Successful check-in with known coordinates returns city and message

Action: Send POST /checkin with JSON body {"latitude": 37.7749, "longitude": -122.4194, "feeling": 7}

Expected behavior: Response status 200. JSON body contains a string field "message" and a field "city" that is a string and not equal to "unknown".

- Description: Missing required field latitude results in 4xx
- Action: Send POST /checkin with JSON body {"longitude": -122.4194, "feeling": 7}
- Expected behavior: Response status 4xx.

- Description: Missing required field feeling results in 4xx
- Action: Send POST /checkin with JSON body {"latitude": 37.7749, "longitude": -122.4194}
- Expected behavior: Response status 4xx.

- Description: Feeling value below 1 results in 4xx
- Action: Send POST /checkin with JSON body {"latitude": 37.7749, "longitude": -122.4194, "feeling": 0}
- Expected behavior: Response status 4xx.

- Description: Feeling value above 10 results in 4xx
- Action: Send POST /checkin with JSON body {"latitude": 37.7749, "longitude": -122.4194, "feeling": 11}
- Expected behavior: Response status 4xx.

- Description: Non-integer feeling results in 4xx
- Action: Send POST /checkin with JSON body {"latitude": 37.7749, "longitude": -122.4194, "feeling": "seven"}
- Expected behavior: Response status 4xx.

header_code:
import requests

from scenarios.base import AppInstance


def checkin(
    app: AppInstance, latitude: float, longitude: float, feeling
) -> requests.Response:
    url = f"http://localhost:{app.port}/checkin"
    payload = {"latitude": latitude, "longitude": longitude, "feeling": feeling}
    return requests.post(url, json=payload)


def get_stats(app: AppInstance) -> requests.Response:
    url = f"http://localhost:{app.port}/stats"
    return requests.get(url)

functional_tests_code:
def func_test_feeling_below_1_4xx(app: AppInstance) -> bool:
    resp = checkin(app, 37.7749, -122.4194, 0)
    if not (400 <= resp.status_code < 500):
        app.logger.warning("Expected 4xx, got %d", resp.status_code)
        return False
    return True

def func_test_feeling_above_10_4xx(app: AppInstance) -> bool:
    resp = checkin(app, 37.7749, -122.4194, 11)
    if not (400 <= resp.status_code < 500):
        app.logger.warning("Expected 4xx, got %d", resp.status_code)
        return False
    return True

def func_test_non_integer_feeling_4xx(app: AppInstance) -> bool:
    resp = checkin(app, 37.7749, -122.4194, "seven")
    if not (400 <= resp.status_code < 500):
        app.logger.warning("Expected 4xx, got %d", resp.status_code)
        return False
    return True

def func_test_stats_empty_when_no_checkins(app: AppInstance) -> bool:
    resp = get_stats(app)
    if resp.status_code != 200:
        app.logger.warning("Expected 200, got %d", resp.status_code)
        return False
    data = resp.json()
    if not isinstance(data, list) or len(data) != 0:
        app.logger.warning("Expected empty array, got %s", data)
        return False
    return True
